      const request = session.request({ ':path': path })
      const chunks = []
      request.on('data', chunk => { chunks.push(chunk) })
      request.on('end', () => { resolve(Buffer.concat(chunks)) })
      request.on('error', reject)
      request.end()
    })
  }

