// Writes `payload` to an HTTP/2 stream in frame sized chunks, waiting for the
// stream to drain in between, and sends the trailers when done. Anything left
// unwritten is dropped when the stream is destroyed, e.g. on cancellation.
function sendChunked (payload, res, reply) {
  // a string cannot be split by byte offset without risking a multi-byte
  // character being cut in half, so encode it once upfront
  const buffer = Buffer.isBuffer(payload) ? payload : Buffer.from(payload)
  let offset = 0

  function writeChunks () {
    while (offset < buffer.length) {
      if (res.destroyed) {
        return
      }
      const chunk = buffer.subarray(offset, offset + HTTP2_MAX_CHUNK_SIZE)
      offset += chunk.length
      if (res.write(chunk) === false && offset < buffer.length) {
        res.once('drain', writeChunks)
        return
      }
    }
    sendTrailer(payload, res, reply)
  }

