test('http2 large buffer payload', async t => {
  const fastify = Fastify({ http2: true })
  const payload = Buffer.alloc(1024 * 1024, 'a')

  fastify.get('/large', function (req, reply) {
    reply.header('content-type', 'application/octet-stream').send(payload)
  })

  fastify.get('/small', function (req, reply) {
    reply.send(msg)
  })

  t.after(() => { fastify.close() })

  await fastify.listen({ port: 0 })

  const session = http2.connect(`http://localhost:${fastify.server.address().port}`)
  t.after(() => { session.destroy() })

  function get (path) {
    return new Promise((resolve, reject) => {
      const request = session.request({ ':path': path })
      const chunks = []
      request.on('data', chunk => { chunks.push(chunk) })
      request.on('end', () => { resolve(Buffer.concat(chunks)) })
      request.on('error', reject)
      request.end()
    })
  }

  await t.test('is sent in full', async t => {
    t.plan(1)

    const body = await get('/large')

    t.assert.ok(body.equals(payload))
  })

  await t.test('does not poison the session when cancelled', async t => {
    t.plan(1)

    await new Promise((resolve, reject) => {
      const request = session.request({ ':path': '/large' })
      request.once('data', () => {
        request.close(http2.constants.NGHTTP2_CANCEL)
        resolve()
      })
      request.on('error', noop)
      request.on('close', resolve)
      request.end()
    })

    // the session is shared, so the cancelled stream must not stop the next one
    const body = await get('/small')

    t.assert.deepStrictEqual(JSON.parse(body.toString()), msg)
  })
})

